def test_running_container_transport_receipt_uses_containerized_live_mode(tmp_path: Path) -> None:
    fixture = Path("spectator/public/battle-fixtures/battle-004-pr6-genetic-pixi/battle.normalized_ux_fixture.json")
    source = build_live_transport_source(fixture_path=fixture, battle_id="battle-004")
    websocket_server = create_live_websocket_transport_server(source=source, host="127.0.0.1", port=0)
    websocket_port = int(websocket_server.socket.getsockname()[1])
    server = create_live_transport_server(
        source=source,
        host="127.0.0.1",
        port=0,
        websocket_port=websocket_port,
    )
    port = int(server.server_address[1])

    import threading

    http_thread = threading.Thread(target=server.serve_forever, daemon=True)
    ws_thread = threading.Thread(target=websocket_server.serve_forever, daemon=True)
    ws_thread.start()
    http_thread.start()
    try:
        receipt = _prove_running_container_transport(
            out_dir=tmp_path,
            base_url=f"http://127.0.0.1:{port}",
            websocket_url=f"ws://127.0.0.1:{websocket_port}/battle/live/battle-004/ws",
            battle_id="battle-004",
            health={
                "schema": "battle.live_transport_health.v1",
                "status": "PASS",
                "battle_id": "battle-004",
                "websocket_endpoint": "/battle/live/battle-004/ws",
                "websocket_port": websocket_port,
            },
        )
    finally:
        server.shutdown()
        server.server_close()
        websocket_server.shutdown()
        http_thread.join(timeout=5)
        ws_thread.join(timeout=5)

    assert receipt["status"] == "PASS"
    assert receipt["mocked"] is False
    assert receipt["live"] == "containerized_http_sse_websocket_adapter"
    assert receipt["websocket_matches_sse_payloads"] is True
    stored = json.loads((tmp_path / "containerized-live-transport-proof.json").read_text(encoding="utf-8"))
    assert stored["schema"] == "battle.containerized_live_transport_proof.v1"
